// 이동·무기: 서버(판정)와 클라이언트(예측)가 똑같이 돌려야 하므로 여기 한 곳에만 둔다
export const TICK = 1 / 60;
export const P = { hw: 0.3, h: 1.85, eye: 1.6, speed: 6, jump: 8, gravity: 24 };
export const KEY = { F: 1, B: 2, L: 4, R: 8, J: 16, FIRE: 32, RELOAD: 64 };
export const MAX_HP = 100;
// 단위: 틱(1/60초), 라디안
export const GUN = {
  name: '소총', mag: 25, rate: 6, reload: 120, dmg: 25, headMul: 2, range: 120,
  spread: 0.004, moveSpread: 0.03, airSpread: 0.08, heatSpread: 0.004, heatMax: 10,
};
const EPS = 1e-4;

export function newState([x, y, z]) {
  return { x, y, z, vx: 0, vy: 0, vz: 0, g: false, ammo: GUN.mag, cd: 0, rl: 0, heat: 0 };
}

function hits(map, x, y, z) {
  const x0 = Math.floor(x - P.hw + EPS), x1 = Math.floor(x + P.hw - EPS);
  const y0 = Math.floor(y + EPS), y1 = Math.floor(y + P.h - EPS);
  const z0 = Math.floor(z - P.hw + EPS), z1 = Math.floor(z + P.hw - EPS);
  for (let j = y0; j <= y1; j++)
    for (let k = z0; k <= z1; k++)
      for (let i = x0; i <= x1; i++)
        if (map.solid(i, j, k)) return true;
  return false;
}

// inp = { k: 키 비트, y: yaw }
export function stepPlayer(s, inp, map) {
  const k = inp.k, yaw = inp.y;
  const mz = (k & KEY.F ? 1 : 0) - (k & KEY.B ? 1 : 0);
  const mx = (k & KEY.R ? 1 : 0) - (k & KEY.L ? 1 : 0);
  let dx = -Math.sin(yaw) * mz + Math.cos(yaw) * mx;
  let dz = -Math.cos(yaw) * mz - Math.sin(yaw) * mx;
  const len = Math.hypot(dx, dz);
  if (len > 0) { dx /= len; dz /= len; }
  s.vx = dx * P.speed;
  s.vz = dz * P.speed;
  if (k & KEY.J && s.g) s.vy = P.jump;
  s.vy = Math.max(s.vy - P.gravity * TICK, -30);

  let nx = s.x + s.vx * TICK;
  if (hits(map, nx, s.y, s.z)) {
    nx = s.vx > 0 ? Math.floor(nx + P.hw) - P.hw - EPS * 2 : Math.floor(nx - P.hw) + 1 + P.hw + EPS * 2;
    if (hits(map, nx, s.y, s.z)) nx = s.x;
    s.vx = 0;
  }
  s.x = nx;

  let nz = s.z + s.vz * TICK;
  if (hits(map, s.x, s.y, nz)) {
    nz = s.vz > 0 ? Math.floor(nz + P.hw) - P.hw - EPS * 2 : Math.floor(nz - P.hw) + 1 + P.hw + EPS * 2;
    if (hits(map, s.x, s.y, nz)) nz = s.z;
    s.vz = 0;
  }
  s.z = nz;

  let ny = s.y + s.vy * TICK;
  s.g = false;
  if (hits(map, s.x, ny, s.z)) {
    if (s.vy < 0) { ny = Math.floor(ny) + 1; s.g = true; }
    else ny = Math.floor(ny + P.h) - P.h - EPS * 2;
    if (hits(map, s.x, ny, s.z)) ny = s.y;
    s.vy = 0;
  }
  s.y = ny;
}

// 쏘면 탄 퍼짐(라디안)을, 안 쏘면 -1을 돌려준다
export function stepWeapon(s, k) {
  if (s.cd > 0) s.cd--;
  s.heat = Math.max(0, s.heat - 0.15);
  if (s.rl > 0) {
    if (--s.rl === 0) s.ammo = GUN.mag;
    return -1;
  }
  if (k & KEY.RELOAD && s.ammo < GUN.mag) { s.rl = GUN.reload; return -1; }
  if (!(k & KEY.FIRE) || s.cd > 0) return -1;
  if (s.ammo <= 0) { s.rl = GUN.reload; return -1; }
  const moving = Math.hypot(s.vx, s.vz) > 0.5;
  const spread = (s.g ? (moving ? GUN.moveSpread : GUN.spread) : GUN.airSpread) + s.heat * GUN.heatSpread;
  s.ammo--;
  s.cd = GUN.rate;
  s.heat = Math.min(GUN.heatMax, s.heat + 1);
  return spread;
}

// 같은 seed면 서버와 클라이언트가 같은 값을 얻는 난수 (0~1)
function rand(n) {
  n = Math.imul(n ^ 0x9e3779b9, 0x85ebca6b);
  n ^= n >>> 13;
  n = Math.imul(n, 0xc2b2ae35);
  n ^= n >>> 16;
  return (n >>> 0) / 4294967296;
}

export function aimDir(yaw, pitch) {
  const c = Math.cos(pitch);
  return [-Math.sin(yaw) * c, Math.sin(pitch), -Math.cos(yaw) * c];
}

export function shotDir(yaw, pitch, spread, seed) {
  const a = rand(seed) * Math.PI * 2, m = Math.sqrt(rand(seed * 31 + 7)) * spread;
  return aimDir(yaw + (Math.cos(a) * m) / Math.max(Math.cos(pitch), 0.2), pitch + Math.sin(a) * m);
}

// 사격 판정용 광선 검사 (서버 판정 + 클라이언트 탄 궤적 표시)

// 블록 격자를 한 칸씩 따라가며(DDA) 처음 닿는 블록을 찾는다
export function rayBlocks(map, o, d, max) {
  const cell = [Math.floor(o[0]), Math.floor(o[1]), Math.floor(o[2])];
  const step = [0, 0, 0], tMax = [0, 0, 0], tDelta = [0, 0, 0];
  for (let i = 0; i < 3; i++) {
    step[i] = Math.sign(d[i]);
    tDelta[i] = d[i] !== 0 ? Math.abs(1 / d[i]) : Infinity;
    tMax[i] = d[i] > 0 ? (cell[i] + 1 - o[i]) / d[i] : d[i] < 0 ? (o[i] - cell[i]) / -d[i] : Infinity;
  }
  let t = 0, axis = -1;
  while (t <= max) {
    if (axis >= 0 && map.solid(cell[0], cell[1], cell[2])) {
      const n = [0, 0, 0];
      n[axis] = -step[axis];
      return { t, cell: [...cell], n };
    }
    axis = tMax[0] < tMax[1] ? (tMax[0] < tMax[2] ? 0 : 2) : (tMax[1] < tMax[2] ? 1 : 2);
    cell[axis] += step[axis];
    t = tMax[axis];
    tMax[axis] += tDelta[axis];
  }
  return null;
}

// 광선이 상자(min~max)에 닿는 거리, 안 닿으면 Infinity
export function rayBox(o, d, min, max) {
  let t0 = 0, t1 = Infinity;
  for (let i = 0; i < 3; i++) {
    if (d[i] === 0) {
      if (o[i] < min[i] || o[i] > max[i]) return Infinity;
      continue;
    }
    let a = (min[i] - o[i]) / d[i], b = (max[i] - o[i]) / d[i];
    if (a > b) [a, b] = [b, a];
    t0 = Math.max(t0, a);
    t1 = Math.min(t1, b);
    if (t0 > t1) return Infinity;
  }
  return t0;
}

// 플레이어 발 위치 기준 머리·몸통 판정 상자
export function hitboxes({ x, y, z }) {
  return [
    { head: true, min: [x - 0.25, y + 1.38, z - 0.25], max: [x + 0.25, y + 1.88, z + 0.25] },
    { head: false, min: [x - 0.4, y, z - 0.4], max: [x + 0.4, y + 1.38, z + 0.4] },
  ];
}

// 게임 서버: 정적 파일 + WebSocket. 위치·사격은 서버가 판정하고 클라이언트는 입력만 보낸다
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { WebSocketServer } from 'ws';
import { createMap, SPAWNS } from '../shared/map.js';
import { TICK, P, GUN, MAX_HP, newState, stepPlayer, stepWeapon, shotDir } from '../shared/sim.js';
import { rayBlocks, rayBox, hitboxes } from '../shared/ray.js';

const PORT = Number(process.env.PORT) || 3000;
const ROOT = path.resolve(fileURLToPath(new URL('..', import.meta.url)));
const MAX_PLAYERS = 5;
const SNAPSHOT_EVERY = 3; // 60틱 중 3틱마다 = 초당 20번
const HISTORY = 60; // 되감기용 위치 기록 (1초)
const MAX_REWIND = 40; // 쏜 사람 화면 기준으로 최대 0.67초까지 되감아 판정
const RESPAWN = 300; // 5초 (3단계 라운드 전까지 임시)
const COLORS = ['#e8505b', '#3d8bfd', '#f2b632', '#2fbf71', '#a259ff'];

// ---- 정적 파일 ----
const ROUTES = [
  ['/vendor/', 'node_modules/three/build/'],
  ['/client/', 'client/'],
  ['/shared/', 'shared/'],
];
const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };

const server = http.createServer((req, res) => {
  let p;
  try { p = decodeURIComponent(new URL(req.url, 'http://x').pathname); } catch { p = ''; }
  if (p === '/') p = '/client/index.html';
  let file = null;
  for (const [prefix, dir] of ROUTES) {
    if (!p.startsWith(prefix)) continue;
    const base = path.join(ROOT, dir);
    const f = path.join(base, p.slice(prefix.length));
    if (f.startsWith(base)) file = f;
  }
  if (!file) { res.writeHead(404).end('not found'); return; }
  fs.readFile(file, (err, data) => {
    if (err) { res.writeHead(404).end('not found'); return; }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' }).end(data);
  });
});

// ---- 방 ----
const map = createMap();
const rooms = new Map();
let nextId = 1;
let tick = 0;

function makeCode() {
  const letters = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  let code;
  do code = Array.from({ length: 4 }, () => letters[Math.floor(Math.random() * letters.length)]).join('');
  while (rooms.has(code));
  return code;
}

function send(ws, msg) {
  if (ws.readyState === ws.OPEN) ws.send(JSON.stringify(msg));
}

function broadcast(room, msg, except = null) {
  const data = JSON.stringify(msg);
  for (const p of room.players.values())
    if (p !== except && p.ws.readyState === p.ws.OPEN) p.ws.send(data);
}

function roster(room) {
  broadcast(room, {
    t: 'roster',
    players: [...room.players.values()].map((p) => ({ id: p.id, name: p.name, color: p.color, kills: p.kills, deaths: p.deaths })),
  });
}

// 살아 있는 다른 플레이어에게서 가장 먼 부활 지점
function farthestSpawn(room, self) {
  let best = SPAWNS[0], bestD = -1;
  for (const sp of SPAWNS) {
    let d = Infinity;
    for (const q of room.players.values())
      if (q !== self && q.alive) d = Math.min(d, Math.hypot(q.state.x - sp[0], q.state.z - sp[2]));
    if (d > bestD) { bestD = d; best = sp; }
  }
  return best;
}

function join(ws, msg) {
  const name = String(msg.name || '').trim().slice(0, 12) || '플레이어';
  let code = String(msg.room || '').trim().toUpperCase();
  let room;
  if (code) {
    room = rooms.get(code);
    if (!room) return send(ws, { t: 'error', msg: `방 ${code}을(를) 찾을 수 없습니다.` });
  } else {
    code = makeCode();
    room = { code, players: new Map() };
    rooms.set(code, room);
  }
  if (room.players.size >= MAX_PLAYERS) return send(ws, { t: 'error', msg: '방이 가득 찼습니다.' });

  const used = new Set([...room.players.values()].map((p) => p.slot));
  const slot = [...Array(MAX_PLAYERS).keys()].find((i) => !used.has(i));
  const p = {
    id: nextId++, ws, name, slot, color: COLORS[slot], room,
    state: null, queue: [], lastSeq: 0, yaw: 0, pitch: 0,
    hp: MAX_HP, alive: true, respawnAt: 0, kills: 0, deaths: 0, hist: [],
  };
  p.state = newState(farthestSpawn(room, p));
  room.players.set(p.id, p);
  send(ws, { t: 'welcome', id: p.id, room: code, state: p.state });
  roster(room);
  return p;
}

function leave(p) {
  const room = p.room;
  room.players.delete(p.id);
  if (room.players.size === 0) rooms.delete(room.code);
  else roster(room);
}

// rt 틱(소수 가능) 때 q가 있던 위치. 기록이 없으면 null
function positionAt(q, rt) {
  const h = q.hist;
  const find = (t) => h[h.length - 1 - (tick - t)];
  const a = find(Math.floor(rt)), b = find(Math.ceil(rt));
  if (!a || !b) return null;
  if (!a.alive || !b.alive) return null;
  const f = rt - Math.floor(rt);
  return { x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f, z: a.z + (b.z - a.z) * f };
}

function fire(room, p, inp, spread) {
  const s = p.state;
  const o = [s.x, s.y + P.eye, s.z];
  const d = shotDir(inp.y, inp.p, spread, inp.s);
  const wall = rayBlocks(map, o, d, GUN.range);
  let best = wall ? wall.t : GUN.range, target = null, head = false;
  const rt = Math.min(tick, Math.max(tick - MAX_REWIND, inp.rt));
  for (const q of room.players.values()) {
    if (q === p || !q.alive) continue;
    const pos = positionAt(q, rt);
    if (!pos) continue;
    for (const hb of hitboxes(pos)) {
      const t = rayBox(o, d, hb.min, hb.max);
      if (t < best) { best = t; target = q; head = hb.head; }
    }
  }
  const e = o.map((v, i) => v + d[i] * best);
  broadcast(room, { t: 'fx', id: p.id, o, e, hit: target ? target.id : 0 }, p);
  if (!target) return;

  target.hp -= GUN.dmg * (head ? GUN.headMul : 1);
  const kill = target.hp <= 0;
  send(p.ws, { t: 'hit', id: target.id, head, kill });
  send(target.ws, { t: 'hurt', x: s.x, z: s.z });
  if (!kill) return;
  target.hp = 0;
  target.alive = false;
  target.respawnAt = tick + RESPAWN;
  target.deaths++;
  p.kills++;
  broadcast(room, { t: 'kill', k: p.id, v: target.id, head, respawn: RESPAWN * TICK });
  roster(room);
}

const wss = new WebSocketServer({ server, maxPayload: 1024 });
wss.on('connection', (ws) => {
  let me = null;
  ws.on('message', (raw) => {
    let msg;
    try { msg = JSON.parse(raw); } catch { return; }
    if (msg.t === 'join' && !me) me = join(ws, msg) || null;
    else if (msg.t === 'ping') send(ws, { t: 'pong', c: msg.c });
    else if (msg.t === 'i' && me) {
      const k = msg.k | 0, s = msg.s | 0;
      if (k < 0 || k > 127 || s <= me.lastSeq) return;
      if (![msg.y, msg.p, msg.rt].every(Number.isFinite)) return;
      me.queue.push({ s, k, y: msg.y, p: Math.max(-1.55, Math.min(1.55, msg.p)), rt: msg.rt });
      if (me.queue.length > 30) me.queue.shift();
    }
  });
  ws.on('close', () => { if (me) leave(me); });
});

// ---- 게임 루프 ----
setInterval(() => {
  tick++;
  for (const room of rooms.values()) {
    for (const p of room.players.values()) {
      // 한 틱에 최대 3개까지만 처리: 입력을 몰아 보내 빨리 움직이는 것 방지
      for (let n = 0; n < 3 && p.queue.length; n++) {
        const inp = p.queue.shift();
        p.lastSeq = inp.s;
        if (!p.alive) continue;
        p.yaw = inp.y;
        p.pitch = inp.p;
        stepPlayer(p.state, inp, map);
        const spread = stepWeapon(p.state, inp.k);
        if (spread >= 0) fire(room, p, inp, spread);
      }
      if (!p.alive && tick >= p.respawnAt) {
        p.state = newState(farthestSpawn(room, p));
        p.hp = MAX_HP;
        p.alive = true;
      }
      if (p.state.y < -10) p.state = newState(farthestSpawn(room, p));
    }
    for (const p of room.players.values()) {
      p.hist.push({ x: p.state.x, y: p.state.y, z: p.state.z, alive: p.alive });
      if (p.hist.length > HISTORY) p.hist.shift();
    }
    if (tick % SNAPSHOT_EVERY === 0) {
      broadcast(room, {
        t: 's',
        tick,
        ps: [...room.players.values()].map((p) => {
          const s = p.state;
          return [p.id, s.x, s.y, s.z, s.vx, s.vy, s.vz, s.g ? 1 : 0, p.yaw, p.pitch, p.lastSeq,
            p.hp, p.alive ? 1 : 0, s.ammo, s.cd, s.rl, s.heat];
        }),
      });
    }
  }
}, TICK * 1000);

