// 장면, 블록 맵, 플레이어 아바타
import * as THREE from 'three';
import { W, D, H, B } from '/shared/map.js';

export const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
document.body.prepend(renderer.domElement);

export const scene = new THREE.Scene();
scene.background = new THREE.Color('#8fc9f0');
scene.fog = new THREE.Fog('#8fc9f0', 30, 75);
scene.add(new THREE.HemisphereLight('#ffffff', '#6b7a5a', 1.6));
const sun = new THREE.DirectionalLight('#ffffff', 1.4);
sun.position.set(30, 50, 15);
scene.add(sun);

export const camera = new THREE.PerspectiveCamera(80, innerWidth / innerHeight, 0.05, 200);
camera.rotation.order = 'YXZ';
camera.position.set(W / 2, 12, D + 6);
camera.lookAt(W / 2, 0, D / 2);
scene.add(camera); // 총 모델을 카메라에 붙이기 위해

addEventListener('resize', () => {
  renderer.setSize(innerWidth, innerHeight);
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
});

// ---- 맵 그리기: 겉으로 드러난 블록만 InstancedMesh 하나로 ----
function blockTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 16;
  const g = c.getContext('2d');
  g.fillStyle = '#ffffff';
  g.fillRect(0, 0, 16, 16);
  g.strokeStyle = 'rgba(0,0,0,0.18)';
  g.strokeRect(0.5, 0.5, 15, 15);
  const tex = new THREE.CanvasTexture(c);
  tex.magFilter = THREE.NearestFilter;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export const BLOCK_COLORS = {
  [B.FLOOR]: ['#6cbf5a', '#63b352'],
  [B.WALL]: ['#8a909b', '#828893'],
  [B.STONE]: ['#c9bfa8', '#beb49c'],
  [B.CRATE]: ['#c98a3e', '#bd8037'],
  [B.COVER]: ['#5b7fbf', '#5377b5'],
};

export function buildWorld(map) {
  const list = [];
  for (let y = 0; y < H; y++)
    for (let z = 0; z < D; z++)
      for (let x = 0; x < W; x++) {
        const b = map.get(x, y, z);
        if (!b) continue;
        const exposed = !map.solid(x + 1, y, z) || !map.solid(x - 1, y, z) || !map.solid(x, y + 1, z)
          || (y > 0 && !map.solid(x, y - 1, z)) || !map.solid(x, y, z + 1) || !map.solid(x, y, z - 1);
        if (exposed) list.push([x, y, z, b]);
      }
  const mesh = new THREE.InstancedMesh(
    new THREE.BoxGeometry(1, 1, 1),
    new THREE.MeshLambertMaterial({ map: blockTexture() }),
    list.length,
  );
  const m = new THREE.Matrix4(), col = new THREE.Color();
  list.forEach(([x, y, z, b], i) => {
    m.setPosition(x + 0.5, y + 0.5, z + 0.5);
    mesh.setMatrixAt(i, m);
    mesh.setColorAt(i, col.set(BLOCK_COLORS[b][(x + y + z) & 1]));
  });
  scene.add(mesh);
}

// ---- 아바타 ----
function part(w, h, d, color, x, y, z) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), new THREE.MeshLambertMaterial({ color }));
  mesh.position.set(x, y, z);
  return mesh;
}

function nameTag(text) {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 64;
  const g = c.getContext('2d');
  g.font = 'bold 34px system-ui, sans-serif';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.lineWidth = 6;
  g.strokeStyle = 'rgba(0,0,0,0.6)';
  g.strokeText(text, 128, 32);
  g.fillStyle = '#fff';
  g.fillText(text, 128, 32);
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(c), depthTest: false }));
  sprite.scale.set(1.6, 0.4, 1);
  sprite.position.y = 2.2;
  return sprite;
}

// 팔다리는 관절(pivot) 그룹 안에 넣어 흔들기
function limb(w, h, color, x, y) {
  const pivot = new THREE.Group();
  pivot.position.set(x, y, 0);
  pivot.add(part(w, h, w, color, 0, -h / 2, 0));
  return pivot;
}

export function makeAvatar(name, color) {
  const root = new THREE.Group();
  const body = new THREE.Group(); // 쓰러질 때 발을 축으로 눕힌다
  const skin = '#f2d0a4', pants = '#2d3550';
  const legL = limb(0.27, 0.7, pants, -0.15, 0.7), legR = limb(0.27, 0.7, pants, 0.15, 0.7);
  const armL = limb(0.22, 0.65, color, -0.42, 1.38), armR = limb(0.22, 0.65, color, 0.42, 1.38);
  // 오른손에 든 총 (팔 방향 = 팔 기준 -y)
  armR.add(part(0.1, 0.55, 0.12, '#2b2b30', 0, -0.75, -0.02));
  armL.rotation.z = -0.35;
  const torso = part(0.6, 0.68, 0.32, color, 0, 1.05, 0);
  const head = new THREE.Group();
  head.position.y = 1.39;
  head.add(part(0.46, 0.46, 0.46, skin, 0, 0.24, 0));
  head.add(part(0.07, 0.1, 0.02, '#1d1d1d', -0.1, 0.28, -0.235));
  head.add(part(0.07, 0.1, 0.02, '#1d1d1d', 0.1, 0.28, -0.235));
  body.add(legL, legR, armL, armR, torso, head);
  const tag = nameTag(name);
  root.add(body, tag);
  scene.add(root);
  const mats = [];
  body.traverse((o) => { if (o.material) mats.push(o.material); });
  return { root, body, head, legL, legR, armL, armR, tag, mats, phase: 0, fall: 0, flash: 0 };
}

export function removeAvatar(a) {
  scene.remove(a.root);
  a.root.traverse((o) => { o.geometry?.dispose(); o.material?.map?.dispose(); o.material?.dispose(); });
}

// 총 모델, 탄 궤적, 파편, 소리
import * as THREE from 'three';
import { scene, camera } from './world.js';

// ---- 1인칭 총 모델 ----
const gun = new THREE.Group();
const gunMat = (color) => new THREE.MeshLambertMaterial({ color, fog: false });
function gunPart(w, h, d, color, x, y, z) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), gunMat(color));
  m.position.set(x, y, z);
  gun.add(m);
  return m;
}
gunPart(0.07, 0.09, 0.5, '#2b2b30', 0, 0, -0.1);      // 몸통
gunPart(0.05, 0.05, 0.22, '#3a3a42', 0, 0.02, -0.45); // 총열
gunPart(0.06, 0.14, 0.07, '#e07a2f', 0, -0.1, -0.08); // 탄창
gunPart(0.06, 0.13, 0.06, '#2b2b30', 0, -0.1, 0.08);  // 손잡이
gunPart(0.03, 0.04, 0.04, '#e07a2f', 0, 0.065, 0.05); // 가늠자
const flash = new THREE.Mesh(
  new THREE.BoxGeometry(0.1, 0.1, 0.1),
  new THREE.MeshBasicMaterial({ color: '#ffd84a', fog: false }),
);
flash.position.set(0, 0.02, -0.6);
flash.visible = false;
gun.add(flash);
const muzzle = new THREE.Object3D();
muzzle.position.set(0, 0.02, -0.58);
gun.add(muzzle);

const GUN_REST = new THREE.Vector3(0.22, -0.2, -0.38);
gun.position.copy(GUN_REST);
camera.add(gun);

let kick = 0, flashT = 0, reloadDip = 0;

export function setGunVisible(v) { gun.visible = v; }

export function muzzleWorld() {
  return muzzle.getWorldPosition(new THREE.Vector3());
}

export function gunFired() {
  kick = 1;
  flashT = 0.04;
  flash.visible = true;
  flash.rotation.z = Math.random() * Math.PI;
}

// reloading: 0~1 진행도 (재장전 아니면 -1), moving: 걷는 중이면 흔들기
let bob = 0;
export function updateGun(dt, reloading, moving) {
  kick = Math.max(0, kick - dt * 12);
  flashT -= dt;
  if (flashT <= 0) flash.visible = false;
  reloadDip += ((reloading >= 0 ? 1 : 0) - reloadDip) * Math.min(1, dt * 12);
  bob += dt * (moving ? 10 : 0);
  const sway = moving ? 1 : 0;
  gun.position.set(
    GUN_REST.x + Math.sin(bob) * 0.012 * sway,
    GUN_REST.y - reloadDip * 0.12 + Math.abs(Math.cos(bob)) * 0.012 * sway,
    GUN_REST.z + kick * 0.06,
  );
  gun.rotation.set(kick * 0.12 - reloadDip * 0.6, 0, reloadDip * 0.4);
}

// ---- 탄 궤적과 파편 ----
const live = [];
const tracerMat = new THREE.LineBasicMaterial({ color: '#fff2a8', transparent: true });
const cubeGeo = new THREE.BoxGeometry(1, 1, 1);

export function tracer(from, to) {
  const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
  const line = new THREE.Line(geo, tracerMat.clone());
  scene.add(line);
  live.push({ obj: line, life: 0.08, max: 0.08, kind: 'tracer' });
}

export function burst(at, color, n = 5, size = 0.08) {
  for (let i = 0; i < n; i++) {
    const m = new THREE.Mesh(cubeGeo, new THREE.MeshLambertMaterial({ color }));
    m.scale.setScalar(size * (0.6 + Math.random() * 0.8));
    m.position.copy(at);
    scene.add(m);
    live.push({
      obj: m, life: 0.5, max: 0.5, kind: 'bit',
      v: new THREE.Vector3((Math.random() - 0.5) * 4, Math.random() * 3 + 1, (Math.random() - 0.5) * 4),
    });
  }
}

export function updateFx(dt) {
  for (let i = live.length - 1; i >= 0; i--) {
    const p = live[i];
    p.life -= dt;
    if (p.kind === 'tracer') p.obj.material.opacity = Math.max(0, p.life / p.max);
    else {
      p.v.y -= 12 * dt;
      p.obj.position.addScaledVector(p.v, dt);
      p.obj.rotation.x += dt * 8;
    }
    if (p.life <= 0) {
      scene.remove(p.obj);
      p.obj.material.dispose();
      if (p.kind === 'tracer') p.obj.geometry.dispose();
      live.splice(i, 1);
    }
  }
}

// ---- 소리 (파일 없이 WebAudio로 합성) ----
let ac = null;
export function initAudio() {
  if (!ac) try { ac = new AudioContext(); } catch { ac = null; }
  ac?.resume?.();
}

function noise(dur, vol, freq) {
  if (!ac) return;
  const len = Math.floor(ac.sampleRate * dur);
  const buf = ac.createBuffer(1, len, ac.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len) ** 2;
  const src = ac.createBufferSource();
  src.buffer = buf;
  const f = ac.createBiquadFilter();
  f.type = 'lowpass';
  f.frequency.value = freq;
  const g = ac.createGain();
  g.gain.value = vol;
  src.connect(f).connect(g).connect(ac.destination);
  src.start();
}

function tone(freq, dur, vol, delay = 0) {
  if (!ac) return;
  const o = ac.createOscillator(), g = ac.createGain();
  o.type = 'square';
  o.frequency.value = freq;
  const t = ac.currentTime + delay;
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  o.connect(g).connect(ac.destination);
  o.start(t);
  o.stop(t + dur);
}

export const sfx = {
  shot: () => noise(0.12, 0.35, 2400),
  far: (dist) => noise(0.1, Math.max(0.03, 0.25 - dist * 0.006), 1200),
  hit: (head) => tone(head ? 1400 : 900, 0.06, 0.08),
  kill: () => { tone(700, 0.08, 0.08); tone(1050, 0.12, 0.08, 0.08); },
  hurt: () => noise(0.15, 0.3, 500),
  empty: () => tone(300, 0.04, 0.05),
};

import * as THREE from 'three';
import { createMap } from '/shared/map.js';
import { TICK, P, KEY, GUN, MAX_HP, stepPlayer, stepWeapon, shotDir } from '/shared/sim.js';
import { rayBlocks, rayBox, hitboxes } from '/shared/ray.js';
import { renderer, scene, camera, buildWorld, makeAvatar, removeAvatar, BLOCK_COLORS } from './world.js';
import { setGunVisible, muzzleWorld, gunFired, updateGun, tracer, burst, updateFx, initAudio, sfx } from './fx.js';

const $ = (id) => document.getElementById(id);
const map = createMap();
buildWorld(map);

// ---- 입력 ----
const keys = new Set();
let yaw = 0, pitch = 0, firing = false;
const SENS = 0.0022;
const locked = () => document.pointerLockElement === renderer.domElement;
const lockPointer = () => renderer.domElement.requestPointerLock()?.catch?.(() => {});

addEventListener('keydown', (e) => {
  if (e.code === 'Tab' && joined) { e.preventDefault(); $('board').classList.remove('hidden'); }
  if (!locked()) return;
  keys.add(e.code);
  if (e.code === 'Space') e.preventDefault();
});
addEventListener('keyup', (e) => {
  keys.delete(e.code);
  if (e.code === 'Tab') $('board').classList.add('hidden');
});
addEventListener('blur', () => { keys.clear(); firing = false; });
addEventListener('mousemove', (e) => {
  if (!locked()) return;
  yaw -= e.movementX * SENS;
  pitch = Math.max(-1.55, Math.min(1.55, pitch - e.movementY * SENS));
});
addEventListener('mousedown', (e) => { if (locked() && e.button === 0) firing = true; });
addEventListener('mouseup', (e) => { if (e.button === 0) firing = false; });
document.addEventListener('pointerlockchange', () => {
  if (!locked()) { keys.clear(); firing = false; }
  if (joined) $('resume').classList.toggle('hidden', locked());
});
$('resume').addEventListener('click', () => { initAudio(); lockPointer(); });

function keyBits() {
  let k = 0;
  if (keys.has('KeyW')) k |= KEY.F;
  if (keys.has('KeyS')) k |= KEY.B;
  if (keys.has('KeyA')) k |= KEY.L;
  if (keys.has('KeyD')) k |= KEY.R;
  if (keys.has('Space')) k |= KEY.J;
  if (keys.has('KeyR')) k |= KEY.RELOAD;
  if (firing) k |= KEY.FIRE;
  return k;
}

// ---- 상태 ----
let ws = null, joined = false, myId = 0;
let me = null, prev = null, seq = 0, pending = [];
let alive = true, hp = MAX_HP, killerId = 0, respawnAt = 0;
const players = new Map(); // id -> { name, color, kills, deaths }
const others = new Map(); // id -> avatar
let snaps = []; // [{ t, tick, ps: Map }]
const INTERP_MS = 100;

$('name').value = storageGet('name');
$('join').addEventListener('click', connect);
for (const id of ['name', 'room']) $(id).addEventListener('keydown', (e) => { if (e.key === 'Enter') connect(); });

function storageGet(k) { try { return localStorage.getItem(k) || ''; } catch { return ''; } }
function storageSet(k, v) { try { localStorage.setItem(k, v); } catch {} }

function connect() {
  if (ws) return;
  initAudio();
  $('error').textContent = '';
  const name = $('name').value.trim();
  storageSet('name', name);
  ws = new WebSocket(`${location.protocol === 'https:' ? 'wss' : 'ws'}://${location.host}`);
  ws.onopen = () => ws.send(JSON.stringify({ t: 'join', name, room: $('room').value.trim() }));
  ws.onmessage = (e) => onMessage(JSON.parse(e.data));
  ws.onclose = () => {
    const wasJoined = joined;
    ws = null; joined = false;
    for (const a of others.values()) removeAvatar(a);
    others.clear();
    players.clear();
    snaps = [];
    for (const id of ['hud', 'resume', 'death', 'board']) $(id).classList.add('hidden');
    $('lobby').classList.remove('hidden');
    if (wasJoined) $('error').textContent = '서버와 연결이 끊겼습니다.';
    else if (!$('error').textContent) $('error').textContent = '서버에 연결할 수 없습니다.';
  };
}

const nameOf = (id) => players.get(id)?.name ?? '?';

function onMessage(msg) {
  switch (msg.t) {
    case 'error':
      $('error').textContent = msg.msg;
      ws.close();
      break;
    case 'welcome':
      joined = true;
      myId = msg.id;
      me = { ...msg.state };
      prev = { ...me };
      seq = 0; pending = [];
      alive = true; hp = MAX_HP;
      setGunVisible(true);
      $('code').textContent = msg.room;
      $('lobby').classList.add('hidden');
      $('hud').classList.remove('hidden');
      $('resume').classList.remove('hidden');
      lockPointer();
      break;
    case 'roster': onRoster(msg.players); break;
    case 's': onSnapshot(msg); break;
    case 'fx': onFx(msg); break;
    case 'hit': {
      sfx.hit(msg.head);
      showHitmarker(msg.head, msg.kill);
      if (msg.kill) sfx.kill();
      const a = others.get(msg.id);
      if (a) {
        a.flash = 0.12;
        burst(a.root.position.clone().add(new THREE.Vector3(0, msg.head ? 1.6 : 1, 0)), players.get(msg.id)?.color ?? '#fff', 6);
      }
      break;
    }
    case 'hurt':
      sfx.hurt();
      $('vignette').style.transition = 'none';
      $('vignette').style.opacity = '1';
      requestAnimationFrame(() => {
        $('vignette').style.transition = 'opacity 0.5s';
        $('vignette').style.opacity = '0';
      });
      break;
    case 'kill': onKill(msg); break;
    case 'pong':
      $('ping').textContent = `${Math.round(performance.now() - msg.c)} ms`;
      break;
  }
}

function onRoster(list) {
  const ids = new Set();
  players.clear();
  for (const p of list) {
    ids.add(p.id);
    players.set(p.id, p);
    if (p.id !== myId && !others.has(p.id)) others.set(p.id, makeAvatar(p.name, p.color));
  }
  for (const [id, a] of others) if (!ids.has(id)) { removeAvatar(a); others.delete(id); }

  $('players').innerHTML = '';
  for (const p of list) {
    const li = document.createElement('li');
    li.innerHTML = '<i></i><span></span>';
    li.querySelector('i').style.background = p.color;
    li.querySelector('span').textContent = p.name + (p.id === myId ? ' (나)' : '');
    $('players').append(li);
  }
  const rows = [...list].sort((a, b) => b.kills - a.kills || a.deaths - b.deaths);
  $('board-rows').innerHTML = '';
  for (const p of rows) {
    const tr = document.createElement('tr');
    if (p.id === myId) tr.className = 'me';
    tr.innerHTML = '<td><i></i><span></span></td><td></td><td></td>';
    tr.querySelector('i').style.background = p.color;
    tr.querySelector('span').textContent = p.name;
    tr.children[1].textContent = p.kills;
    tr.children[2].textContent = p.deaths;
    $('board-rows').append(tr);
  }
}

function onSnapshot(msg) {
  const ps = new Map();
  for (const [id, x, y, z, vx, vy, vz, g, pyaw, ppitch, last, php, palive, ammo, cd, rl, heat] of msg.ps) {
    ps.set(id, { x, y, z, yaw: pyaw, pitch: ppitch, alive: !!palive });
    if (id !== myId) continue;
    hp = php;
    pending = pending.filter((inp) => inp.s > last);
    const wasAlive = alive;
    alive = !!palive;
    if (alive) {
      // 서버 상태로 맞춘 뒤, 서버가 아직 처리 안 한 입력을 다시 적용 (예측 보정)
      me = { x, y, z, vx, vy, vz, g: !!g, ammo, cd, rl, heat };
      for (const inp of pending) { stepPlayer(me, inp, map); stepWeapon(me, inp.k); }
      if (!wasAlive) { prev = { ...me }; onRespawn(); }
    }
  }
  snaps.push({ t: performance.now(), tick: msg.tick, ps });
  if (snaps.length > 30) snaps.shift();
}

function onRespawn() {
  setGunVisible(true);
  $('death').classList.add('hidden');
  killerId = 0;
}

function onKill({ k, v, head, respawn }) {
  const li = document.createElement('li');
  li.innerHTML = '<span class="k"></span><span class="arrow"></span><span class="v"></span>';
  li.querySelector('.k').textContent = nameOf(k);
  li.querySelector('.k').style.color = players.get(k)?.color ?? '#fff';
  li.querySelector('.arrow').textContent = head ? ' ▸ 헤드샷 ▸ ' : ' ▸ ';
  li.querySelector('.v').textContent = nameOf(v);
  li.querySelector('.v').style.color = players.get(v)?.color ?? '#fff';
  if (k === myId || v === myId) li.className = 'mine';
  $('feed').prepend(li);
  setTimeout(() => li.remove(), 5000);
  while ($('feed').children.length > 5) $('feed').lastChild.remove();

  if (v === myId) {
    alive = false;
    killerId = k;
    respawnAt = performance.now() + respawn * 1000;
    firing = false;
    setGunVisible(false);
    $('death-by').textContent = `${nameOf(k)}에게 당했습니다`;
    $('death').classList.remove('hidden');
  } else if (k === myId) {
    centerMsg(`${nameOf(v)} 처치${head ? ' (헤드샷)' : ''}`);
  }
}

let centerTimer = 0;
function centerMsg(text) {
  $('center').textContent = text;
  $('center').classList.remove('hidden');
  clearTimeout(centerTimer);
  centerTimer = setTimeout(() => $('center').classList.add('hidden'), 1500);
}

let hitTimer = 0;
function showHitmarker(head, kill) {
  const el = $('hitmarker');
  el.className = kill ? 'kill' : head ? 'head' : '';
  clearTimeout(hitTimer);
  hitTimer = setTimeout(() => el.classList.add('hidden'), kill ? 300 : 150);
}

setInterval(() => { if (joined) ws.send(JSON.stringify({ t: 'ping', c: performance.now() })); }, 2000);

// ---- 보간: 100ms 전 시점을 그린다. 그 시점의 서버 틱을 사격 판정에 함께 보낸다 ----
const lerp = (a, b, t) => a + (b - a) * t;
function lerpAngle(a, b, t) {
  let d = b - a;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return a + d * t;
}

function viewAt(now) {
  if (!snaps.length) return null;
  const t = now - INTERP_MS;
  let s0 = snaps[0], s1 = snaps[0];
  if (t >= snaps[snaps.length - 1].t) s0 = s1 = snaps[snaps.length - 1];
  else for (let i = 0; i < snaps.length - 1; i++)
    if (snaps[i + 1].t >= t) { s0 = snaps[i]; s1 = snaps[i + 1]; break; }
  const f = s1.t > s0.t ? Math.max(0, Math.min(1, (t - s0.t) / (s1.t - s0.t))) : 0;
  return { s0, s1, f, tick: lerp(s0.tick, s1.tick, f) };
}

function posAt(view, id) {
  const p0 = view.s0.ps.get(id), p1 = view.s1.ps.get(id) ?? p0;
  if (!p0) return null;
  // 부활처럼 순간이동한 경우엔 보간하지 않음
  const f = Math.hypot(p1.x - p0.x, p1.z - p0.z) > 3 ? 1 : view.f;
  return {
    x: lerp(p0.x, p1.x, f), y: lerp(p0.y, p1.y, f), z: lerp(p0.z, p1.z, f),
    yaw: lerpAngle(p0.yaw, p1.yaw, f), pitch: lerp(p0.pitch, p1.pitch, f), alive: p1.alive,
  };
}

function updateOthers(view, dt, hideId) {
  for (const [id, a] of others) {
    const p = view && posAt(view, id);
    if (!p) { a.root.visible = false; continue; }
    a.root.visible = id !== hideId;
    const speed = Math.hypot(p.x - a.root.position.x, p.z - a.root.position.z) / Math.max(dt, 1e-3);
    a.root.position.set(p.x, p.y, p.z);
    a.root.rotation.y = p.yaw;
    a.head.rotation.x = p.pitch * 0.6;
    a.armR.rotation.x = a.armL.rotation.x = Math.PI / 2 + p.pitch;
    const amt = p.alive ? Math.min(1, speed / P.speed) : 0;
    a.phase += dt * 10 * amt;
    const swing = Math.sin(a.phase) * 0.7 * amt;
    a.legL.rotation.x = swing;
    a.legR.rotation.x = -swing;
    a.fall += ((p.alive ? 0 : 1) - a.fall) * Math.min(1, dt * 8);
    a.body.rotation.x = -a.fall * Math.PI / 2;
    a.tag.visible = p.alive;
    a.flash = Math.max(0, a.flash - dt);
    for (const m of a.mats) m.emissive.setScalar(a.flash > 0 ? 0.6 : 0);
  }
}

// ---- 사격 표시 ----
function localShot(inp, spread) {
  const o = [me.x, me.y + P.eye, me.z];
  const d = shotDir(inp.y, inp.p, spread, inp.s);
  const wall = rayBlocks(map, o, d, GUN.range);
  let best = wall ? wall.t : GUN.range, hitPlayer = false;
  for (const a of others.values()) {
    if (!a.root.visible || a.fall > 0.5) continue;
    for (const hb of hitboxes(a.root.position)) {
      const t = rayBox(o, d, hb.min, hb.max);
      if (t < best) { best = t; hitPlayer = true; }
    }
  }
  const end = new THREE.Vector3(o[0] + d[0] * best, o[1] + d[1] * best, o[2] + d[2] * best);
  tracer(muzzleWorld(), end);
  if (wall && !hitPlayer) {
    const b = map.get(...wall.cell);
    burst(end, BLOCK_COLORS[b]?.[0] ?? '#888', 4, 0.06);
  }
  gunFired();
  sfx.shot();
}

function onFx({ id, o, e, hit }) {
  const from = new THREE.Vector3(o[0], o[1] - 0.25, o[2]);
  const to = new THREE.Vector3(...e);
  tracer(from, to);
  if (hit && hit !== myId) burst(to, players.get(hit)?.color ?? '#fff', 5);
  else if (!hit) burst(to, '#999', 3, 0.05);
  sfx.far(me ? Math.hypot(o[0] - me.x, o[2] - me.z) : 30);
}

// ---- HUD ----
function updateHud(now) {
  $('hp-num').textContent = alive ? hp : 0;
  $('hp-bar').style.width = `${(alive ? hp : 0) / MAX_HP * 100}%`;
  $('hp-bar').className = hp <= 30 ? 'low' : '';
  $('ammo-num').textContent = me.ammo;
  $('ammo-max').textContent = `/ ${GUN.mag}`;
  $('reload').classList.toggle('hidden', !(alive && me.rl > 0));
  if (!alive) $('death-timer').textContent = `${Math.max(0, Math.ceil((respawnAt - now) / 1000))}초 후 부활`;
}

// ---- 메인 루프: 60틱 고정 시뮬레이션 + 화면은 보간 ----
let acc = 0, last = performance.now();
function frame(now) {
  const dt = Math.min(0.25, (now - last) / 1000);
  last = now;
  if (joined) {
    const view = viewAt(now);
    acc += dt;
    while (acc >= TICK) {
      acc -= TICK;
      const inp = { s: ++seq, k: alive ? keyBits() : 0, y: yaw, p: pitch, rt: view ? Math.round(view.tick * 100) / 100 : 0 };
      if (alive) {
        prev = { ...me };
        stepPlayer(me, inp, map);
        const spread = stepWeapon(me, inp.k);
        if (spread >= 0) localShot(inp, spread);
      }
      pending.push(inp);
      if (pending.length > 120) pending.shift();
      ws.send(JSON.stringify({ t: 'i', ...inp }));
    }

    // 죽었으면 나를 쏜 사람 시점으로 관전
    let spectating = 0;
    if (alive) {
      const a = acc / TICK;
      camera.position.set(lerp(prev.x, me.x, a), lerp(prev.y, me.y, a) + P.eye, lerp(prev.z, me.z, a));
      camera.rotation.set(pitch, yaw, 0);
    } else if (view) {
      const k = posAt(view, killerId);
      if (k && k.alive) {
        spectating = killerId;
        camera.position.set(k.x, k.y + P.eye, k.z);
        camera.rotation.set(k.pitch, k.yaw, 0);
      }
    }
    updateOthers(view, dt, spectating);
    updateGun(dt, me.rl > 0 ? 1 - me.rl / GUN.reload : -1, alive && me.g && Math.hypot(me.vx, me.vz) > 0.5);
    updateHud(now);
  }
  updateFx(dt);
  renderer.render(scene, camera);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

