// 사격 판정 테스트: B가 C를 쏜다 (몸통 4발 처치 → 부활 → 머리 2발 처치)
import WebSocket from '~/04_GitHub/block-arena/node_modules/ws/wrapper.mjs';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function client(name, room) {
  const ws = new WebSocket('ws://localhost:3123');
  await new Promise((r) => ws.on('open', r));
  const c = { ws, log: [], pos: new Map(), tick: 0, seq: 0, id: 0, room: null };
  ws.on('message', (d) => {
    const m = JSON.parse(d);
    if (m.t === 'welcome') { c.id = m.id; c.room = m.room; }
    else if (m.t === 's') { c.tick = m.tick; for (const p of m.ps) c.pos.set(p[0], p); }
    else if (m.t !== 'pong' && m.t !== 'roster') c.log.push(m);
    if (m.t === 'roster') c.roster = m.players;
  });
  ws.send(JSON.stringify({ t: 'join', name, room }));
  await sleep(200);
  return c;
}
const input = (c, k, y, p) => c.ws.send(JSON.stringify({ t: 'i', s: ++c.seq, k, y, p, rt: c.tick }));

const A = await client('A');
const Bc = await client('B', A.room);
const C = await client('C', A.room);
// 모두 떨어져 착지하도록 잠깐 입력
for (let i = 0; i < 20; i++) { for (const x of [A, Bc, C]) input(x, 0, 0, 0); await sleep(16); }
await sleep(200);
const b = Bc.pos.get(Bc.id), cc = Bc.pos.get(C.id);
console.log('B at', b.slice(1, 4).map((v) => v.toFixed(1)), 'C at', cc.slice(1, 4).map((v) => v.toFixed(1)));

async function shootAt(targetH, ticks) {
  const t = Bc.pos.get(C.id);
  const o = [b[1], b[2] + 1.6, b[3]];
  const v = [t[1] - o[0], t[2] + targetH - o[1], t[3] - o[2]];
  const yaw = Math.atan2(-v[0], -v[2]), pitch = Math.atan2(v[1], Math.hypot(v[0], v[2]));
  for (let i = 0; i < ticks; i++) {
    input(Bc, 32, yaw, pitch); input(C, 0, 0, 0); input(A, 0, 0, 0);
    await sleep(16.6);
  }
  input(Bc, 0, yaw, pitch);
}
await shootAt(1.0, 30);
await sleep(300);
console.log('B log:', JSON.stringify(Bc.log));
console.log('C log:', JSON.stringify(C.log.map((m) => m.t)));
console.log('C alive in snapshot:', Bc.pos.get(C.id)[12], 'hp', Bc.pos.get(C.id)[11], 'B ammo', Bc.pos.get(Bc.id)[13]);
console.log('roster', JSON.stringify(Bc.roster.map((p) => [p.name, p.kills, p.deaths])));
// 부활 대기
for (let i = 0; i < 330; i++) { for (const x of [A, Bc, C]) input(x, 0, 0, 0); await sleep(16.6); }
const c2 = Bc.pos.get(C.id);
console.log('C after respawn alive', c2[12], 'hp', c2[11], 'at', c2.slice(1, 4).map((v) => v.toFixed(1)));
process.exit(0);

