// 3단계 라운드 흐름 테스트 (서버를 DEV=1로 띄워야 함)
import WebSocket from '~/04_GitHub/block-arena/node_modules/ws/wrapper.mjs';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function client(name, room) {
  const ws = new WebSocket('ws://localhost:3123');
  await new Promise((r) => ws.on('open', r));
  const c = { ws, name, log: [], me: null, all: new Map(), tick: 0, seq: 0, id: 0, room: null, ph: null, zone: null };
  ws.on('message', (d) => {
    const m = JSON.parse(d);
    if (m.t === 'welcome') { c.id = m.id; c.room = m.room; }
    else if (m.t === 's') {
      c.tick = m.tick; c.ph = m.ph; c.zone = m.z;
      for (const p of m.ps) c.all.set(p[0], p);
      c.me = c.all.get(c.id);
    } else if (['phase', 'roundEnd', 'matchEnd', 'kill'].includes(m.t)) c.log.push(m);
  });
  ws.send(JSON.stringify({ t: 'join', name, room }));
  await sleep(200);
  // 계속 빈 입력을 보내 서버가 처리하게
  c.keys = 0; c.yaw = 0; c.pitch = 0;
  c.timer = setInterval(() => ws.send(JSON.stringify({ t: 'i', s: ++c.seq, k: c.keys, y: c.yaw, p: c.pitch, rt: c.tick })), 16.6);
  return c;
}
const info = (c) => c.me && { hp: c.me[11], alive: c.me[12], w: c.me[17], money: c.me[19], ammo: c.me[13], pos: [c.me[1], c.me[3]].map((v) => +v.toFixed(1)) };
const waitPhase = async (c, ph) => { while (c.ph !== ph) await sleep(50); };
const tp = (c, x, y, z) => c.ws.send(JSON.stringify({ t: 'tp', x, y, z }));
const buy = (c, w) => c.ws.send(JSON.stringify({ t: 'buy', w }));
const ok = (cond, label) => console.log(cond ? 'OK  ' : 'FAIL', label);

// shooter가 target을 쏴서 죽일 때까지 (단발은 눌렀다 뗐다)
async function killIt(sh, tg) {
  tp(sh, 43.5, 1, 43.5); tp(tg, 4.5, 1, 43.5);
  await sleep(300);
  for (let i = 0; i < 400 && tg.me[12]; i++) {
    const a = sh.me, b = sh.all.get(tg.id);
    const v = [b[1] - a[1], b[2] + 1.0 - (a[2] + 1.6), b[3] - a[3]];
    sh.yaw = Math.atan2(-v[0], -v[2]); sh.pitch = Math.atan2(v[1], Math.hypot(v[0], v[2]));
    sh.keys = i % 2 ? 32 : 0;
    await sleep(34);
  }
  sh.keys = 0;
}

const A = await client('A');
const B = await client('B', A.room);
await sleep(300);
ok(A.ph === 'L', `대기실 ${A.ph}`);
await waitPhase(A, 'B');
await sleep(200);
ok(info(A).money === 800 && info(B).money === 800, `1라운드 시작 돈 800 ${JSON.stringify(info(A))}`);
buy(A, 1); await sleep(200);
ok(info(A).w === 0 && info(A).money === 800, '800으로 기관단총(1600) 못 삼');
const before = info(A).pos;
A.keys = 1; await sleep(800); A.keys = 32; await sleep(300); A.keys = 0;
ok(JSON.stringify(info(A).pos) === JSON.stringify(before) && info(A).ammo === 12, `구매 시간엔 못 움직이고 못 쏨 ${JSON.stringify(info(A))}`);

await waitPhase(A, 'R');
console.log('전투 시작, 자기장', A.zone);
await killIt(A, B);
await sleep(300);
const re = A.log.find((m) => m.t === 'roundEnd');
ok(re && re.winner === A.id, `A 라운드 승리 ${JSON.stringify(re)}`);
ok(A.ph === 'E', `라운드 끝 단계 ${A.ph}`);
ok(info(A).money === 3900 && info(B).money === 2700, `돈 A 3900 B 2700: ${info(A).money} ${info(B).money}`);

await waitPhase(A, 'B');
await sleep(200);
buy(A, 2); await sleep(150);
ok(info(A).w === 2 && info(A).money === 1000, `소총 구매 → 1000: ${JSON.stringify(info(A))}`);
buy(A, 3); await sleep(150);
ok(info(A).w === 3 && info(A).money === 2100, `샷건으로 바꿈(환불) → 2100: ${info(A).money}`);
buy(A, 2); await sleep(150);
ok(info(A).w === 2 && info(A).money === 1000, `다시 소총 → 1000: ${info(A).money}`);
buy(B, 1); await sleep(150);
ok(info(B).w === 1 && info(B).money === 1100, `B 기관단총 → 1100: ${info(B).money}`);

await waitPhase(A, 'R');
// 라운드 도중 C 입장 → 관전
const C = await client('C', A.room);
await sleep(300);
ok(info(C).alive === 0, 'C는 라운드 도중이라 관전');
// A를 구석(처음 원 밖)에 두고 자기장 피해 확인
tp(A, 2, 1, 2); tp(B, 24, 3, 24);
await sleep(23000);
ok(info(A).hp < 100, `자기장 밖 피해: A hp ${info(A).hp}, 자기장 ${JSON.stringify(A.zone)}`);
ok(info(B).hp === 100, `안쪽 B hp ${info(B).hp}`);
await killIt(A, B);
await waitPhase(A, 'B');
await sleep(300);
ok(info(A).w === 2 && info(B).w === 0, `살아남은 A는 소총 유지, 죽은 B는 권총: A ${info(A).w} B ${info(B).w}`);
ok(info(C).alive === 1, 'C 다음 라운드에 참가');
console.log('roster wins:', A.log.filter((m) => m.t === 'roundEnd').map((m) => m.winner), 'A id', A.id);
process.exit(0);

