for (let z = 3; z < 45 && !crate; z++) for (let x = 3; x < 45 && !crate; x++)
  if (m.get(x, 1, z) === B.CRATE && !m.get(x, 2, z) && m.get(x + 1, 1, z) === B.CRATE && !m.get(x, 1, z + 2) && !m.get(x, 1, z + 3) && !m.get(x, 1, z + 4) && !m.get(x, 1, z - 1) && !m.get(x, 1, z - 2) && !m.get(x, 1, z - 3)) crate = [x, z];
console.log('상자', crate);
const [cx, cz] = crate;

const A = await client('A');
A.ws.send(JSON.stringify({ t: 'buy', w: 2 })); // 대기실이라 공짜
