// 상자 앞(+z쪽 4칸)에서 상자 아래칸 가운데를 쏜다
tp(A, cx + 0.5, 1, cz + 5.5);
await sleep(300);
aim(A, cx + 0.5, 1.5, cz + 0.5);
A.keys = 32; await sleep(250); A.keys = 0;
await sleep(300);
const blk = A.log.filter((x) => x.t === 'blk');
ok(blk.some((x) => x.c.some(([x1, y1, z1, b]) => x1 === cx && y1 === 1 && z1 === cz && b === 0)), `상자 부서짐 ${JSON.stringify(blk)} 탄약 ${A.me[13]}`);

// 늦게 들어온 B는 바뀐 칸을 welcome으로 받음
