ok(Bc.welcome.changes.some(([x1, y1, z1, b]) => x1 === cx && y1 === 1 && z1 === cz && b === 0), `도중 입장 changes ${JSON.stringify(Bc.welcome.changes)}`);

// 부서진 칸 뒤의 B를 같은 선으로 맞힐 수 있는지
tp(Bc, cx + 0.5, 1, cz - 2.5);
