// 규칙 카드 테스트 (DEV=1). 라운드마다 A가 B → C 순으로 처치, B가 카드를 고름
import WebSocket from '~/04_GitHub/block-arena/node_modules/ws/wrapper.mjs';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function client(name, room) {
  const ws = new WebSocket('ws://localhost:3123');
  await new Promise((r) => ws.on('open', r));
  const c = { ws, log: [], all: new Map(), tick: 0, seq: 0, id: 0, room: null, ph: null, keys: 0, yaw: 0, pitch: 0, snap: null };
  ws.on('message', (d) => {
    const m = JSON.parse(d);
    if (m.t === 'welcome') { c.id = m.id; c.room = m.room; }
    else if (m.t === 's') { c.snap = m; c.tick = m.tick; c.ph = m.ph; for (const p of m.ps) c.all.set(p[0], p); c.me = c.all.get(c.id); }
    else c.log.push(m);
  });
  ws.send(JSON.stringify({ t: 'join', name, room }));
  await sleep(200);
  c.timer = setInterval(() => ws.send(JSON.stringify({ t: 'i', s: ++c.seq, k: c.keys, y: c.yaw, p: c.pitch, rt: c.tick })), 16.6);
  return c;
}
const ok = (cond, label) => console.log(cond ? 'OK  ' : 'FAIL', label);
const tp = (c, x, y, z) => c.ws.send(JSON.stringify({ t: 'tp', x, y, z }));
const waitPhase = async (c, ph) => { while (c.ph !== ph) await sleep(50); };
const aimAt = (c, tx, ty, tz) => {
  const v = [tx - c.me[1], ty - (c.me[2] + 1.6), tz - c.me[3]];
  c.yaw = Math.atan2(-v[0], -v[2]); c.pitch = Math.atan2(v[1], Math.hypot(v[0], v[2]));
};
async function killIt(sh, tg, h = 1.0) {
  tp(sh, 43.5, 1, 43.5); tp(tg, 4.5, 1, 43.5);
  await sleep(300);
  for (let i = 0; i < 300 && tg.me[12]; i++) { const b = sh.all.get(tg.id); aimAt(sh, b[1], b[2] + h, b[3]); sh.keys = i % 2 ? 32 : 0; await sleep(34); }
  sh.keys = 0;
}

const A = await client('A');
const Bc = await client('B', A.room);
const C = await client('C', A.room);
const tested = new Set();
for (let round = 1; round <= 4; round++) {
  await waitPhase(A, 'R');
  const card = A.snap.rc?.[0] ?? null;
  console.log(`-- ${round}라운드 카드: ${card}`);
  if (round === 1) ok(card === null, '1라운드는 카드 없음');
  if (card === 'lowgrav') {
    tp(A, 24, 3, 24); await sleep(300);
    let peak = 0; A.keys = 16; for (let i = 0; i < 60; i++) { peak = Math.max(peak, A.me[2]); await sleep(16); } A.keys = 0;
    ok(peak - 3 > 2.5, `저중력 점프 높이 ${(peak - 3).toFixed(2)} (보통 1.33)`);
  }
  if (card === 'giant') ok(A.me[11] === 200 && A.snap.rc[1] === A.id, `거인 A 체력 ${A.me[11]}`);
  if (card === 'headonly') {
    tp(A, 43.5, 1, 43.5); tp(Bc, 4.5, 1, 43.5); await sleep(300);
    const hits0 = A.log.filter((m) => m.t === 'hit').length;
    for (let i = 0; i < 12; i++) { const b = A.all.get(Bc.id); aimAt(A, b[1], b[2] + 0.8, b[3]); A.keys = i % 2 ? 32 : 0; await sleep(34); }
    A.keys = 0; await sleep(300);
    ok(A.log.filter((m) => m.t === 'hit').length === hits0 && Bc.me[11] === 100, `헤드샷만: 몸통 6발에도 B 체력 ${Bc.me[11]}`);
  }
  if (card === 'blockbullet') {
    // 사분면 벽 (x=12, z=9..11) 을 옆에서 쏜다
    tp(A, 16.5, 1, 10.5); await sleep(300);
    const n0 = A.log.filter((m) => m.t === 'blk').length;
    for (let i = 0; i < 16; i++) { aimAt(A, 12.5, 1.5, 10.5); A.keys = i % 2 ? 32 : 0; await sleep(220); }
    A.keys = 0; await sleep(300);
    ok(A.log.filter((m) => m.t === 'blk').slice(n0).some((m) => m.c.some(([x, y, z, b]) => x === 12 && z === 10 && b === 0)), '블록 탄: 회색 벽이 부서짐');
  }
  if (card) tested.add(card);
  await killIt(A, Bc, card === 'headonly' ? 1.63 : 1.0);
  await sleep(200);
  await killIt(A, C, card === 'headonly' ? 1.63 : 1.0);
  await waitPhase(A, 'E');
  await sleep(300);
  const offer = Bc.log.filter((m) => m.t === 'cards').at(-1);
  ok(offer && offer.chooser === Bc.id && offer.options.length === 3, `먼저 죽은 B에게 카드 3장: ${JSON.stringify(offer)}`);
  // 아직 안 해 본 카드를 우선 고름
  let i = offer.options.findIndex((c) => !tested.has(c) && c !== 'fog' && c !== 'reverse');
  if (i < 0) i = 0;
  C.ws.send(JSON.stringify({ t: 'pick', i: (i + 1) % 3 })); // 고를 권한 없는 C → 무시돼야 함
  await sleep(100);
  Bc.ws.send(JSON.stringify({ t: 'pick', i }));
  await sleep(200);
  const picked = A.log.filter((m) => m.t === 'picked').at(-1);
  ok(picked && picked.card === offer.options[i], `B가 고른 카드 ${picked?.card}`);
  await waitPhase(A, 'B');
  await sleep(200);
  ok(A.log.filter((m) => m.t === 'card').at(-1)?.card === offer.options[i], '다음 라운드에 그 카드 적용');
}
process.exit(0);

